#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/flutter/tasks/setup-deps-flutter.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install the Dart, Flutter, CocoaPods and Gradle dependencies, then report the outdated ones; --upgrade cleans and upgrades them"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="clean all caches and lockfiles, then upgrade the dependencies, major versions included"

import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The plugin id of the ben-manes versions plugin, as the regular expression
# of grep: each dot is any character.
VERSIONS_PLUGIN = re.compile(rb"com.github.ben-manes.versions")


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def run(*args, cwd=None, **kwargs):
  """Run a command that mise does not install, and return its exit code. A
  missing command gives 127, as in the shell."""
  try:
    return exit_code(subprocess.run(args, check=False, cwd=cwd, **kwargs).returncode)
  except FileNotFoundError:
    print(f"{args[0]}: command not found", file=sys.stderr, flush=True)
    return 127


def check(code):
  """Stop the task with the code of a command that failed, as set -e does."""
  if code != 0:
    sys.exit(code)


def tool(*args):
  """Run a tool of mise and stop the task when it fails."""
  check(exit_code(helpers.tool(*args).returncode))


def has_versions_plugin(folder):
  """Whether a file below folder names the ben-manes versions plugin. As grep
  -r does, it does not follow a symlink."""
  for parent, dirs, files in os.walk(folder):
    for name in files:
      path = os.path.join(parent, name)
      if os.path.islink(path) or not os.path.isfile(path):
        continue
      try:
        with open(path, "rb") as data:
          if VERSIONS_PLUGIN.search(data.read()):
            return True
      except OSError:
        continue
  return False


def main():
  # Shipped with the flutter tool. Without a pubspec.yaml, this is not a
  # Flutter project, so the task does not apply and prints nothing.
  root = os.environ["MISE_PROJECT_ROOT"]
  if not os.path.isfile(f"{root}/pubspec.yaml"):
    sys.exit(0)

  os.chdir(root)
  has_pods = os.path.isfile("ios/Podfile")
  has_gradle = os.access("android/gradlew", os.X_OK)
  home = os.path.expanduser("~")

  if os.environ.get("usage_upgrade", "false") == "true":
    helpers.print_header("Upgrading Flutter dependencies ...")

    # The clean comes first, so that the upgrade leaves no dangling
    # dependency. The lockfiles go too: the upgrade then resolves every version
    # again. ~/.dartServer stays: it holds no versions, and a running analysis
    # server writes into it, so rm fails with "Directory not empty".
    helpers.print_subheader("Cleaning the Flutter build and the Dart caches ...")
    tool("flutter", "clean")
    check(run("rm", "-rf", ".dart_tool", "build", "pubspec.lock"))
    tool("dart", "pub", "cache", "clean", "--force")

    if has_pods:
      helpers.print_subheader("Cleaning CocoaPods and Xcode ...")
      check(run("pod", "deintegrate", cwd="ios"))
      check(run("pod", "cache", "clean", "--all", cwd="ios"))
      check(
        run(
          "rm",
          "-rf",
          "ios/Pods",
          "ios/Podfile.lock",
          "ios/.symlinks",
          "ios/Flutter/Flutter.framework",
          "ios/Flutter/Flutter.podspec",
          f"{home}/Library/Caches/CocoaPods",
          f"{home}/Library/Developer/Xcode/DerivedData",
        )
      )

    if has_gradle:
      helpers.print_subheader("Cleaning Gradle ...")
      run("./gradlew", "--stop", cwd="android")
      check(run("rm", "-rf", "android/.gradle", f"{home}/.gradle"))

    helpers.print_subheader("Upgrading the Dart and Flutter packages ...")
    tool("flutter", "pub", "upgrade", "--major-versions")
    locked_pub = []
    locked_pod = []
  else:
    helpers.print_header("Installing Flutter dependencies ...")
    # The lockfiles decide the versions; an install never changes them. A
    # lockfile that does not match its manifest fails the install.
    locked_pub = ["--enforce-lockfile"]
    locked_pod = ["--deployment"]

  helpers.print_subheader("Configuring Flutter ...")
  tool("flutter", "config", "--disable-analytics")
  tool("dart", "--disable-analytics")
  android_home = os.environ.get("ANDROID_HOME", "")
  if android_home:
    tool("flutter", "config", "--android-sdk", android_home)

  if has_gradle:
    helpers.print_subheader("Accepting the Android licenses ...")
    # cmdline-tools 23 has no license prompt: a package install accepts the
    # SDK license and writes licenses/, which Gradle reads before it downloads
    # the NDK and the platforms. Flutter needs platform-tools (adb) anyway.
    tool("android", "sdk", "install", "platform-tools")

  helpers.print_subheader("Installing the Dart and Flutter packages ...")
  tool("flutter", "pub", "get", *locked_pub)

  if has_pods:
    helpers.print_subheader("Installing CocoaPods ...")
    check(run("pod", "install", *locked_pod, cwd="ios"))

  if has_gradle:
    helpers.print_subheader("Refreshing the Gradle dependencies ...")
    check(run("./gradlew", "dependencies", "--refresh-dependencies", cwd="android", stdout=subprocess.DEVNULL))

  # A report only: each command exits 1 when a dependency is outdated.
  helpers.print_subheader("Checking for outdated Flutter packages ...")
  helpers.tool("flutter", "pub", "outdated", "--no-transitive")

  if has_pods:
    helpers.print_subheader("Checking for outdated CocoaPods ...")
    run("pod", "outdated", "--ignore-prerelease", cwd="ios")

  # dependencyUpdates comes from the ben-manes versions plugin. Without it,
  # the Gradle task does not exist.
  if has_gradle and has_versions_plugin("android"):
    helpers.print_subheader("Checking for outdated Gradle dependencies ...")
    run("./gradlew", "dependencyUpdates", cwd="android")


main()
